#!/bin/sh
# Rebuild the transcript bundle with the current kit. Instruction files come from a staged copy (tools/stage2.py):
# the five stock skills under the Apache License 2.0 whole, with the license; the other ten with their name,
# description and a note in place of the body. The files in the real config directory are never changed.
S=${S:?set S to the scratch directory that holds fetched/ and stage/}
KIT="${KIT:-$S/fetched/kitnow/token-radar-01-kit}"
python3 -I "$S/tools/stage2.py" "$S/stage/claude" >/dev/null || exit 1
cd "$KIT" && CLAUDE_CONFIG_DIR="$S/stage/claude" node cli/makefun.mjs bundle --repo /home/user/make-fun --out /home/user/make-fun/token-radar-01/transcripts.tar.gz "$@" \
  --context "$S/stage/claude/skills/synced/account/docx/LICENSE.txt" \
  --mcp "Firecrawl=https://mcp.firecrawl.dev/v2/mcp" --mcp "github=https://api.githubcopilot.com/mcp/" --mcp "claude-code-remote=https://claude.ai/code" \
  --notes "Built in Claude Code on the web, a cloud session. That harness mounts its MCP servers itself and gives the session no MCP config to read, so the endpoints here are the nearest public ones: Firecrawl is the account's claude.ai connector, recorded at Firecrawl's documented hosted endpoint; github is the GitHub MCP server the harness provides through its own repository-scoped proxy, recorded at the upstream server's public endpoint; claude-code-remote is the harness's own session and environment server, which has no public endpoint, recorded at the product that mounts it. Firecrawl fetched make.fun's skill.md and the bounty page and looked up its own endpoint; github listed branches; claude-code-remote read environment docs and set a weekly check-in. None wrote any of the entry's code. The 15 instruction files are stock skills the harness syncs to the account: none was written for this build and the build invoked none of them. Five (docx, pdf, pptx, skill-creator, xlsx) are under the Apache License 2.0 and are uploaded whole, with the license text beside them. The other ten are uploaded with their name and description and a note in place of the body: three carry a license file that forbids passing them to a third party, and seven carry no license at all, so the entrant has no right to pass their text on. The one skill the build did use, the impeccable design plugin, was loaded in-session and is in the transcript. Five subagent sessions are blind reviews of public cover images; they wrote no code." 2>&1 | grep -v "searching \|scanning " | sed -E 's/af_[A-Za-z0-9_-]+/af_***/g; s/AF-[A-Za-z0-9-]+/AF-***/g' | cut -c1-260
